chapter(6, 'Approvals and day close on the phone', 'As the manager, approve a pending expense and read the day closing steps on the phone.', 'Meera (Manager)', 'manager', menu='Admin & Setup > Approvals & audit', display='mobile')
step('Meera opens Admin & Setup and then Approvals & audit.', 'Approvals wait for the manager on the phone too.', target='sel:main', auto=['click:menutop:Admin & Setup', 'click:menuleaf:Approvals & audit'], action='click', expect='The Approvals inbox opens.', check="ctx.page==='approvals'")
read('The tabs are Requests, Expenses and Audit log. Each request shows the person and the reason.', 'The manager reads before agreeing.', target='btn:Requests', expect='The approval tabs.')
click('btn:Expenses', 'Tap Expenses.', 'Expenses entered by staff wait here.', expect='The pending expenses are listed.')
click('btn:Approve', 'Tap Approve on the first expense.', 'The expense is posted and the cash leaves the drawer.', expect='The expense is approved.')
step('Meera opens Accounts & Reports and then Day closing.', 'The close can be started from the phone.', target='sel:main', auto=['menu:Accounts & Reports>Day closing'], action='click', expect='Day closing opens.', check="ctx.page==='closing'")
read('The steps are 1 Preflight, 2 Post room nights, 3 Cash shift, 4 Close business date, 5 Closing summary and 6 Open next day. Each card shows its state: Blocked, To do or Waiting. The preflight lists what must be settled, for example arrivals, expenses and restaurant checks.', 'The same order as on the PC; no step can be skipped.', target='btn:1Preflight', expect='The closing steps and the blockers.')
